export function DialogElement({
  title = "{{title}}",
  body = "{{body}}",
  accent = "{{accent}}",
  open = {{open}},
}) {
  return (
    <div style={{ width: 360, minHeight: 200, boxSizing: "border-box", padding: 4 }}>
      <dialog
        open={open}
        style={{ width: 320, boxSizing: "border-box", font: "15px/1.5 system-ui, sans-serif", color: "#241430",
          background: "#FAF7F2", border: "none", borderRadius: 14, boxShadow: "0 20px 44px rgba(36,20,48,.22)",
          padding: 22, position: "static", margin: 0 }}
      >
        <h3 style={{ margin: "0 0 10px", fontSize: 18, fontWeight: 700 }}>{title}</h3>
        <p style={{ margin: "0 0 20px", color: "#241430cc" }}>{body}</p>
        <div style={{ display: "flex", justifyContent: "flex-end", gap: 10 }}>
          <button type="button" style={{ font: "600 14px system-ui, sans-serif", padding: "9px 16px", borderRadius: 8, border: `2px solid ${accent}`, background: "transparent", color: accent, cursor: "pointer" }}>Cancel</button>
          <button type="button" style={{ font: "600 14px system-ui, sans-serif", padding: "9px 16px", borderRadius: 8, border: `2px solid ${accent}`, background: accent, color: "#FAF7F2", cursor: "pointer" }}>Discard</button>
        </div>
      </dialog>
    </div>
  );
}
